def plan(hashes, gpu, cpu, remote, max_load=None):
    gpu_hits = 0
    for h in hashes:
        if h not in gpu:
            break
        gpu_hits += 1
    loads = []
    for h in hashes[gpu_hits:]:
        if h in cpu:
            loads.append((h, "cpu"))
        elif h in remote:
            loads.append((h, "remote"))
        else:
            break
    if max_load is not None:
        loads = loads[:max_load]
    n_cached = gpu_hits + len(loads)
    return gpu_hits, loads, hashes[n_cached:]

hashes = ["h0","h1","h2","h3","h4","h5","h6","h7"]
gpu    = {"h0","h1"}
cpu    = {"h0","h1","h2","h3","h4","h7"}
remote = {"h0","h1","h2","h3","h4","h5"}
print(plan(hashes, gpu, cpu, remote))
